package net.civeira.phylax.feature.observe.observedembed.domain;

import java.time.LocalDateTime;
import java.time.ZoneId;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.observe.observeddashboard.domain.ObservedDashboardReference;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceReference;

class ObservedEmbedChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_observed_embed_change_set_builder() {
    ObservedEmbedChangeSet one = new ObservedEmbedChangeSet().uid("one").name("one")
        .dashboard(ObservedDashboardReference.of("one")).panelUid("one")
        .origin(ObservedSourceReference.of("one")).tokenHashPlain("one").allowedOrigins("one")
        .maxRange(ObservedEmbedMaxRangeOptions.HOUR).minRefresh(1).allowRaw(true)
        .expiresAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
            .toOffsetDateTime())
        .lastUsedAt(LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid"))
            .toOffsetDateTime())
        .enabled(true).version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getName().get(), "Value must equals to the intial value");
    one.name("two");
    Assertions.assertEquals("two", one.getName().get(), "Value must equals to the assigned value");
    one.unset("name");
    Assertions.assertFalse(one.getName().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedDashboardReference.of("one"), one.getDashboard().get(),
        "Value must equals to the intial value");
    one.dashboard(ObservedDashboardReference.of("two"));
    Assertions.assertEquals(ObservedDashboardReference.of("two"), one.getDashboard().get(),
        "Value must equals to the assigned value");
    one.unset("dashboard");
    Assertions.assertFalse(one.getDashboard().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getPanelUid().get(),
        "Value must equals to the intial value");
    one.panelUid("two");
    Assertions.assertEquals("two", one.getPanelUid().get(),
        "Value must equals to the assigned value");
    one.unset("panelUid");
    Assertions.assertFalse(one.getPanelUid().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedSourceReference.of("one"), one.getOrigin().get(),
        "Value must equals to the intial value");
    one.origin(ObservedSourceReference.of("two"));
    Assertions.assertEquals(ObservedSourceReference.of("two"), one.getOrigin().get(),
        "Value must equals to the assigned value");
    one.unset("origin");
    Assertions.assertFalse(one.getOrigin().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals("one", one.getAllowedOrigins().get(),
        "Value must equals to the intial value");
    one.allowedOrigins("two");
    Assertions.assertEquals("two", one.getAllowedOrigins().get(),
        "Value must equals to the assigned value");
    one.unset("allowedOrigins");
    Assertions.assertFalse(one.getAllowedOrigins().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ObservedEmbedMaxRangeOptions.HOUR, one.getMaxRange().get(),
        "Value must equals to the intial value");
    one.maxRange(ObservedEmbedMaxRangeOptions.SIX_HOURS);
    Assertions.assertEquals(ObservedEmbedMaxRangeOptions.SIX_HOURS, one.getMaxRange().get(),
        "Value must equals to the assigned value");
    one.unset("maxRange");
    Assertions.assertFalse(one.getMaxRange().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(1, one.getMinRefresh().get(), "Value must equals to the intial value");
    one.minRefresh(2);
    Assertions.assertEquals(2, one.getMinRefresh().get(),
        "Value must equals to the assigned value");
    one.unset("minRefresh");
    Assertions.assertFalse(one.getMinRefresh().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(true, one.getAllowRaw().get(), "Value must equals to the intial value");
    one.allowRaw(false);
    Assertions.assertEquals(false, one.getAllowRaw().get(),
        "Value must equals to the assigned value");
    one.unset("allowRaw");
    Assertions.assertFalse(one.getAllowRaw().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getExpiresAt().get(), "Value must equals to the intial value");
    one.expiresAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getExpiresAt().get(), "Value must equals to the assigned value");
    one.unset("expiresAt");
    Assertions.assertFalse(one.getExpiresAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getLastUsedAt().get(), "Value must equals to the intial value");
    one.lastUsedAt(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertEquals(
        LocalDateTime.of(1981, 9, 6, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        one.getLastUsedAt().get(), "Value must equals to the assigned value");
    one.unset("lastUsedAt");
    Assertions.assertFalse(one.getLastUsedAt().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(true, one.getEnabled().get(), "Value must equals to the intial value");
    one.enabled(false);
    Assertions.assertEquals(false, one.getEnabled().get(),
        "Value must equals to the assigned value");
    one.unset("enabled");
    Assertions.assertFalse(one.getEnabled().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
